#pragma once
#include "electrode_heat_feedback.hpp"
#include "binding_seals.hpp"
#include "source-kernel/include/surface_emission.hpp"
namespace electrode_heat_v2 {
namespace se=surface_emission;
// Explicit mapping between parent's accepted IDs and this component's revision.
// Numeric IDs never silently replace the string/hash material/geometry identity.
struct SourceStageBinding {
 std::uint64_t common_state=0,thermal_revision=0,field_state=0,mesh_revision=0,material_revision=0,patch_id=0;
 double field_time=0;std::string mesh_identity,material_hash;
 se::Vector E{},B{};
 bool material_phase_admitted=false,planar_barrier_admitted=false,electron_supply_admitted=false;
};
inline se::Stage accepted_source_stage(const Coupler& heat,const Epoch& epoch,std::size_t patch,const SourceStageBinding& bind) {
 need(epoch.t==heat.state().time&&epoch.revision==heat.state().revision&&bind.common_state>0&&bind.field_state==bind.common_state&&bind.thermal_revision==heat.state().revision&&bind.mesh_revision>0&&bind.material_revision>0&&bind.patch_id>0&&bind.field_time==epoch.t&&bind.mesh_identity==epoch.mesh_revision&&bind.material_hash==epoch.material_hash,"source binding not at common accepted field/thermal/mesh/material state");
 se::Stage s;s.accepted_state=bind.common_state;s.field_accepted_state=bind.field_state;s.thermal_accepted_state=bind.common_state;s.mesh_revision=bind.mesh_revision;s.material_revision=bind.material_revision;s.patch_id=bind.patch_id;s.t=epoch.t;s.dt=epoch.dt;s.stage_time=epoch.t;s.field_time=bind.field_time;s.thermal_time=heat.state().time;s.total_E=bind.E;s.total_B_T=bind.B;s.outward_normal=heat.normal(patch);s.area_m2=heat.area(patch);s.T_K=heat.surface_temperatures().at(patch);s.material_temperature_phase_admitted=bind.material_phase_admitted;s.locally_planar_barrier_admitted=bind.planar_barrier_admitted;s.local_equilibrium_electron_supply_admitted=bind.electron_supply_admitted;return s;
}
struct SourceEventIdentity {std::string producer,state_id,parent_id,channel_id,energy_owner;std::uint64_t sequence=0,owner_sequence=0;};
struct BoundLayerState {se::LayerState native;se::Vector surface_origin_m{};std::size_t patch_index=0;std::string mesh_identity,material_hash,kernel_hash=source_kernel_sha256;};
// Pure candidate for the ONE parent-owned electron. No component population/RNG.
struct BoundLayerTrial {BoundLayerState state;se::LayerExchange exchange;int substeps=0;Transfer heat;std::vector<se::CurrentPath> global_paths;};
inline void admit_origin(const Coupler& heat,std::size_t patch,const se::Vector& x){const auto& p=heat.patch(patch);const auto& g=heat.geometry();for(double v:x)need(finite(v),"nonfinite source origin");double tol=32*eps*std::max({std::abs(g.x0),std::abs(g.y0),g.width,g.thickness});bool horizontal=p.face==Face::LowY||p.face==Face::HighY;double normal=horizontal?x[1]:x[0],wall=horizontal?(p.face==Face::LowY?g.y0:g.y0+g.thickness):(p.face==Face::LowX?g.x0:g.x0+g.width);double along=horizontal?(x[0]-g.x0)/g.width:(x[1]-g.y0)/g.thickness;need(std::abs(normal-wall)<=tol&&along>=p.begin&&along<=p.end&&x[2]>=-.5*g.height&&x[2]<=.5*g.height,"source origin outside selected physical surface patch");}
inline Transfer source_heat(const se::LayerExchange& x,const SourceEventIdentity& id,const se::Vector& wall,double time) {
 Transfer t;t.producer=id.producer;t.state_id=id.state_id;t.parent_id=id.parent_id;t.channel_id=id.channel_id;t.energy_owner=id.energy_owner;t.sequence=id.sequence;t.owner_sequence=id.owner_sequence;t.event_time_s=time;t.x=wall[0];t.y=wall[1];t.certified_source_exchange=true;t.source_wall_J=x.wall_heat_J;t.source_particle_K_change_J=x.particle_K_change_J;t.source_electron_reference_change_J=x.electron_reference_change_J;t.source_image_energy_change_J=x.image_energy_change_J;t.source_field_work_J=x.field_work_J;return t;
}
inline BoundLayerTrial bind_layer_trial(se::LayerTrial layer,const se::Stage& stage,const se::Vector& origin,const SourceEventIdentity& id,bool birth,std::size_t patch,const SourceStageBinding& bind) {
 BoundLayerTrial out;out.exchange=layer.exchange;out.substeps=layer.substeps;out.state={std::move(layer.state),origin,patch,bind.mesh_identity,bind.material_hash};se::Vector wall=origin;
 if(out.state.native.status==se::LayerStatus::Recollected)for(int i=0;i<3;++i)wall[i]+=out.state.native.position_from_surface_m[i];
 const double time=birth?stage.stage_time:out.state.native.current_time_s;
 need(time>=stage.t&&time<=stage.t+stage.dt,"source exchange outside current interval");out.heat=source_heat(out.exchange,id,wall,time);double work=0,activity=0;
 for(auto path:layer.paths){need(path.start_time_s>=stage.t&&path.end_time_s>=path.start_time_s&&path.end_time_s<=stage.t+stage.dt,"source path outside current interval");double expected=0;for(int i=0;i<3;++i)expected+=path.charge_C*stage.total_E[i]*(path.to_m[i]-path.from_m[i]);need(std::abs(path.field_work_J-expected)<=256*eps*(std::abs(expected)+std::abs(path.field_work_J)),"source path field-work is not conjugate to weighted charge/displacement");work+=path.field_work_J;activity+=std::abs(path.field_work_J);for(int i=0;i<3;++i){path.from_m[i]+=origin[i];path.to_m[i]+=origin[i];}out.global_paths.push_back(path);}
 need(std::abs(work-out.exchange.field_work_J)<=(1e-10+256*eps)*(activity+std::abs(out.exchange.field_work_J)),"source external work differs from path work");return out;
}
inline BoundLayerTrial begin_bound_source(const Coupler& heat,const Epoch& epoch,std::size_t patch,const SourceStageBinding& bind,const se::Config& config,const se::LayerPolicy& policy,double weight,double un,double ut,double ua,std::uint64_t event_id,const se::Vector& origin,const SourceEventIdentity& id) {
 admit_origin(heat,patch,origin);
 const auto stage=accepted_source_stage(heat,epoch,patch,bind);const auto flux=se::prepare(stage,config);return bind_layer_trial(se::begin_layer(flux,policy,weight,un,ut,ua,event_id),stage,origin,id,true,patch,bind);
}
inline BoundLayerTrial advance_bound_source(const Coupler& heat,const Epoch& epoch,std::size_t patch,const SourceStageBinding& bind,const BoundLayerState& accepted_layer,const se::LayerPolicy& policy,double duration,const SourceEventIdentity& id) {
 need(accepted_layer.kernel_hash==source_kernel_sha256&&accepted_layer.patch_index==patch&&accepted_layer.mesh_identity==bind.mesh_identity&&accepted_layer.material_hash==bind.material_hash,"persisted source origin/mesh/material binding mismatch");admit_origin(heat,patch,accepted_layer.surface_origin_m);const auto stage=accepted_source_stage(heat,epoch,patch,bind);return bind_layer_trial(se::advance_layer(accepted_layer.native,stage,policy,duration),stage,accepted_layer.surface_origin_m,id,false,patch,bind);
}
inline Transfer collected_source_heat(double work_function_eV,double actual_weighted_incoming_K_J,double weight,bool accommodation_admitted,const SourceEventIdentity& id,const se::Vector& wall,double time) {
 need(finite(actual_weighted_incoming_K_J)&&actual_weighted_incoming_K_J>=0&&finite(weight)&&weight>0,"collection requires actual weighted kinetic J and positive physical weight");const auto l=se::collect_at_material_surface(work_function_eV,actual_weighted_incoming_K_J/weight,weight,accommodation_admitted);se::LayerExchange x{l.physical_electron_number,l.particle_charge_C,l.electrode_charge_C,l.wall_heat_J,l.outgoing_K_J-l.incoming_K_J,l.electron_reference_change_J,l.image_reference_change_J,l.resolved_matching_field_work_J};return source_heat(x,id,wall,time);
}
}

namespace electrode_heat_v2 {
inline void write_bound_layer_state(std::ostream& f,const BoundLayerState& s){
 auto put=[&](const auto& x){f.write(reinterpret_cast<const char*>(&x),sizeof(x));};auto str=[&](const std::string& x){std::uint64_t n=x.size();put(n);f.write(x.data(),n);};std::uint64_t magic=0x424c415945523031ULL;put(magic);str(s.kernel_hash);str(s.mesh_identity);str(s.material_hash);put(std::uint64_t(s.patch_index));for(double x:s.surface_origin_m)put(x);const auto& n=s.native;const auto& p=n.particle;put(p.event_id);put(p.accepted_state);put(p.patch_id);put(p.weight);put(p.normal_metal_energy_eV);put(p.transverse_energy_eV);for(double x:p.proper_velocity_m_s)put(x);const auto& l=p.ledger;for(double x:{l.physical_electron_number,l.particle_charge_C,l.electrode_charge_C,l.wall_heat_J,l.outgoing_K_J,l.incoming_K_J,l.electron_reference_change_J,l.image_reference_change_J,l.resolved_matching_field_work_J})put(x);for(double x:n.position_from_surface_m)put(x);for(double x:n.outward_normal)put(x);for(double x:{n.current_time_s,n.return_overlap_distance_m,n.handoff_distance_m,n.work_function_eV,n.source_energy_scale_eV,n.quantum_magnetic_energy_fraction})put(x);put(n.mesh_revision);put(n.material_revision);put(std::uint32_t(n.status));need(bool(f),"source-layer checkpoint write failed");
}
inline BoundLayerState read_bound_layer_state(std::istream& f){
 auto get=[&](auto& x){f.read(reinterpret_cast<char*>(&x),sizeof(x));need(bool(f),"source-layer checkpoint truncated");};auto str=[&](){std::uint64_t n=0;get(n);need(n<1000000,"source checkpoint string length");std::string x(n,'\0');f.read(x.data(),n);need(bool(f),"source-layer string truncated");return x;};std::uint64_t magic=0,patch=0;get(magic);need(magic==0x424c415945523031ULL,"source-layer checkpoint magic");BoundLayerState s;s.kernel_hash=str();s.mesh_identity=str();s.material_hash=str();get(patch);need(patch<=std::numeric_limits<std::size_t>::max(),"source checkpoint patch overflow");s.patch_index=patch;for(double& x:s.surface_origin_m)get(x);auto& n=s.native;auto& p=n.particle;get(p.event_id);get(p.accepted_state);get(p.patch_id);get(p.weight);get(p.normal_metal_energy_eV);get(p.transverse_energy_eV);for(double& x:p.proper_velocity_m_s)get(x);auto& l=p.ledger;for(double* x:{&l.physical_electron_number,&l.particle_charge_C,&l.electrode_charge_C,&l.wall_heat_J,&l.outgoing_K_J,&l.incoming_K_J,&l.electron_reference_change_J,&l.image_reference_change_J,&l.resolved_matching_field_work_J})get(*x);for(double& x:n.position_from_surface_m)get(x);for(double& x:n.outward_normal)get(x);for(double* x:{&n.current_time_s,&n.return_overlap_distance_m,&n.handoff_distance_m,&n.work_function_eV,&n.source_energy_scale_eV,&n.quantum_magnetic_energy_fraction})get(*x);get(n.mesh_revision);get(n.material_revision);std::uint32_t status=0;get(status);need(status<=std::uint32_t(se::LayerStatus::Recollected),"invalid source-layer status");n.status=static_cast<se::LayerStatus>(status);need(s.kernel_hash==source_kernel_sha256&&!s.mesh_identity.empty()&&!s.material_hash.empty()&&p.event_id>0&&p.accepted_state>0&&p.patch_id>0&&p.weight>0&&n.mesh_revision>0&&n.material_revision>0&&n.current_time_s>=0&&n.work_function_eV>0,"source-layer checkpoint identity/model mismatch");for(double x:s.surface_origin_m)need(finite(x),"nonfinite source origin");for(double x:p.proper_velocity_m_s)need(finite(x),"nonfinite source velocity");for(double x:n.position_from_surface_m)need(finite(x),"nonfinite source position");double norm=0;for(double x:n.outward_normal){need(finite(x),"nonfinite source normal");norm+=x*x;}need(std::abs(norm-1)<=64*eps,"source normal not unit");for(double x:{p.weight,p.normal_metal_energy_eV,p.transverse_energy_eV,l.physical_electron_number,l.particle_charge_C,l.electrode_charge_C,l.wall_heat_J,l.outgoing_K_J,l.incoming_K_J,l.electron_reference_change_J,l.image_reference_change_J,l.resolved_matching_field_work_J,n.current_time_s,n.return_overlap_distance_m,n.handoff_distance_m,n.work_function_eV,n.source_energy_scale_eV,n.quantum_magnetic_energy_fraction})need(finite(x),"nonfinite source checkpoint operand");return s;
}
}
